import os
import sys
import argparse
import fnmatch

def format_size(size, use_bytes=False):
    if use_bytes:
        return f"{size} B"
    if size < 1024:
        return f"{size} B"
    units = ["KiB", "MiB", "GiB", "TiB", "PiB"]
    val = size / 1024
    for unit in units:
        if val < 1024 or unit == "PiB":
            return f"{val:.2f} {unit}"
        val /= 1024
    return f"{val:.2f} PiB"

def get_size(path, use_usage=False):
    try:
        st = os.lstat(path)
        if use_usage:
            return st.st_blocks * 512
        else:
            return st.st_size
    except OSError:
        return 0

class Node:
    def __init__(self, path, name, is_dir):
        self.path = path
        self.name = name
        self.is_dir = is_dir
        self.size = 0
        self.children = []

def build_tree(path, name, exclude_patterns, no_hidden, use_usage, aggregate_threshold, files_only, depth, current_depth=0):
    is_dir = os.path.isdir(path) and not os.path.islink(path)
    node = Node(path, name, is_dir)

    if not is_dir:
        node.size = get_size(path, use_usage)
        return node

    # Directory size
    node.size = get_size(path, use_usage)

    try:
        entries = os.listdir(path)
    except OSError:
        entries = []

    children = []
    for entry in entries:
        if no_hidden and entry.startswith('.'):
            continue
        if any(fnmatch.fnmatch(entry, pat) for pat in exclude_patterns):
            continue

        full_path = os.path.join(path, entry)
        child_is_dir = os.path.isdir(full_path) and not os.path.islink(full_path)

        if files_only and child_is_dir:
            continue

        child_node = build_tree(full_path, entry, exclude_patterns, no_hidden, use_usage, aggregate_threshold, files_only, depth, current_depth + 1)
        if child_node:
            children.append(child_node)
            node.size += sum_sizes(child_node) if child_is_dir else child_node.size

    # Wait, the size of a directory should already include its children?
    # No, get_size(path) only returns the size of the directory entry itself.
    # We need to sum up children's sizes.
    total_size = get_size(path, use_usage)
    for child in children:
        total_size += child.size
    node.size = total_size

    # Aggregate
    if current_depth < depth:
        real_children = []
        aggregated_size = 0
        for child in children:
            if child.size < aggregate_threshold:
                aggregated_size += child.size
            else:
                real_children.append(child)

        real_children.sort(key=lambda x: x.size, reverse=True)
        if aggregated_size > 0:
            agg_node = Node("", "<aggregated>", False)
            agg_node.size = aggregated_size
            real_children.append(agg_node)
        node.children = real_children
    else:
        node.children = [] # Don't show children beyond depth

    return node

def sum_sizes(node):
    return node.size

# Re-implementing build_tree to be more careful about depth and aggregation
def build_tree_v2(path, name, exclude_patterns, no_hidden, use_usage, files_only):
    is_dir = os.path.isdir(path) and not os.path.islink(path)
    node = Node(path, name, is_dir)
    node.size = get_size(path, use_usage)

    if is_dir:
        try:
            entries = os.listdir(path)
        except OSError:
            entries = []
        for entry in entries:
            if no_hidden and entry.startswith('.'):
                continue
            if any(fnmatch.fnmatch(entry, pat) for pat in exclude_patterns):
                continue
            full_path = os.path.join(path, entry)
            if files_only and os.path.isdir(full_path) and not os.path.islink(full_path):
                continue
            child = build_tree_v2(full_path, entry, exclude_patterns, no_hidden, use_usage, files_only)
            node.children.append(child)
            node.size += child.size
    return node

def apply_depth_and_aggregation(node, depth, threshold, current_depth=0):
    if current_depth >= depth:
        node.children = []
        return

    new_children = []
    aggregated_size = 0
    for child in node.children:
        if child.size < threshold:
            aggregated_size += child.size
        else:
            apply_depth_and_aggregation(child, depth, threshold, current_depth + 1)
            new_children.append(child)

    new_children.sort(key=lambda x: x.size, reverse=True)
    if aggregated_size > 0:
        agg_node = Node("", "<aggregated>", False)
        agg_node.size = aggregated_size
        new_children.append(agg_node)
    node.children = new_children

