import os
import sys
import argparse
import fnmatch

def format_size(size, use_bytes=False):
    if use_bytes:
        return f"{size} B"
    if size < 1024:
        return f"{size} B"
    units = ["KiB", "MiB", "GiB", "TiB", "PiB"]
    val = size / 1024
    for unit in units:
        if val < 1024 or unit == "PiB":
            # Rounding: it seems it rounds to 2 decimal places
            return f"{val:.2f} {unit}"
        val /= 1024
    return f"{val:.2f} PiB"

def get_size(path, use_usage=False):
    try:
        st = os.lstat(path)
        if use_usage:
            # st_blocks is usually in 512-byte blocks
            return st.st_blocks * 512
        else:
            return st.st_size
    except OSError:
        return 0

class Node:
    def __init__(self, path, name, is_dir):
        self.path = path
        self.name = name
        self.is_dir = is_dir
        self.size = 0
        self.children = []

def build_tree_full(path, name, exclude_patterns, no_hidden, use_usage, files_only):
    is_dir = os.path.isdir(path) and not os.path.islink(path)
    node = Node(path, name, is_dir)

    # Base size of the directory/file itself
    node.size = get_size(path, use_usage)

    if is_dir:
        try:
            entries = os.listdir(path)
        except OSError:
            entries = []
        for entry in entries:
            if no_hidden and entry.startswith('.'):
                continue
            if any(fnmatch.fnmatch(entry, pat) for pat in exclude_patterns):
                continue
            full_path = os.path.join(path, entry)
            if files_only and os.path.isdir(full_path) and not os.path.islink(full_path):
                continue
            child = build_tree_full(full_path, entry, exclude_patterns, no_hidden, use_usage, files_only)
            if child:
                node.children.append(child)
                node.size += child.size
    return node

def apply_depth_and_aggregation(node, depth, threshold, current_depth=0):
    if current_depth >= depth:
        node.children = []
        return

    new_children = []
    aggregated_size = 0

    # Important: sort children by size descending before aggregating?
    # No, it seems it aggregates all files < threshold regardless of position
    # But then it puts <aggregated> at the end.

    for child in node.children:
        if child.size < threshold:
            aggregated_size += child.size
        else:
            apply_depth_and_aggregation(child, depth, threshold, current_depth + 1)
            new_children.append(child)

    new_children.sort(key=lambda x: x.size, reverse=True)
    if aggregated_size > 0:
        agg_node = Node("", "<aggregated>", False)
        agg_node.size = aggregated_size
        new_children.append(agg_node)
    node.children = new_children

def parse_ls_colors():
    ls_colors = os.environ.get("LS_COLORS", "")
    colors = {}
    for entry in ls_colors.split(':'):
        if '=' in entry:
            key, val = entry.split('=', 1)
            colors[key] = val
    return colors

def get_color_code(path, name, is_dir, colors):
    if is_dir:
        return colors.get("di", "0")
    if path and os.access(path, os.X_OK):
        return colors.get("ex", "0")
    ext = os.path.splitext(name)[1]
    if ext:
        ext_key = "*" + ext
        if ext_key in colors:
            return colors[ext_key]
    return colors.get("fi", "0")

def color_text(text, code, use_color):
    if not use_color or code == "0":
        return text
    return f"\033[{code}m{text}\033[0m"

def print_tree(node, total_root_size, colors, use_color, use_bytes, use_ascii, prefix="", is_last=True, is_root=False, max_sibling_size=None, parent_bar_info=None):
    if is_root:
        print(f"[ {node.name} {format_size(node.size, use_bytes)} ]")
    else:
        connector = "└─ " if is_last else "├─ "
        if use_ascii:
            connector = connector.replace("└", "`").replace("├", "|").replace("─", "-")

        # Bar calculation
        if parent_bar_info:
            p_start, p_width, p_level = parent_bar_info
            if max_sibling_size > 0:
                num_blocks = int(round(node.size / max_sibling_size * p_width))
            else:
                num_blocks = 0
            if num_blocks > p_width: num_blocks = p_width

            bar_chars = []
            for i in range(32):
                if i < p_start:
                    bar_chars.append(' ')
                elif i < 32 - num_blocks:
                    if use_ascii:
                        bar_chars.append(' ') # ASCII mode doesn't have shades? Wait, I should check.
                    else:
                        shades = ['░', '▒', '▓']
                        shade_idx = min(p_level - 1, len(shades) - 1)
                        bar_chars.append(shades[shade_idx])
                else:
                    bar_chars.append('#' if use_ascii else '█')
            bar_str = "".join(bar_chars)
        else:
            # Level 1 children
            if max_sibling_size > 0:
                num_blocks = int(round(node.size / max_sibling_size * 32))
            else:
                num_blocks = 0
            if num_blocks > 32: num_blocks = 32
            bar_str = ' ' * (32 - num_blocks) + ('#' if use_ascii else '█') * num_blocks

        # Fix: in ASCII mode, I saw that Level 1-4 used '#' and spaces
        if use_ascii:
            # Re-check ASCII bars. 
            # In my test: f2 had '                  ###############'
            # So yes, it uses spaces for the "next shade" if it's ASCII!
            # Wait, let me check again.
            pass

        percentage = int(round(node.size / total_root_size * 100)) if total_root_size > 0 else 0

        color_code = get_color_code(node.path, node.name, node.is_dir, colors)
        colored_name = color_text(node.name, color_code, use_color)

        # Alignment
        # Branch+Name should end before the │
        tree_branch = prefix + connector
        # Tree branch is 3 chars per level + connector (3 chars)
        # But wait, prefix is already built.

        line_start = f"{tree_branch}{colored_name}"
        # We need the visible length
        visible_len = len(tree_branch) + len(node.name)
        padding = 26 - visible_len
        if padding < 1: padding = 1

        sep = "|" if use_ascii else "│"

        formatted_size = format_size(node.size, use_bytes)
        print(f"{line_start}{' ' * padding}{sep} {bar_str}{sep} {percentage:3}% {formatted_size:>13}")

    # Recurse
    if node.children:
        branch_pipe = "|" if use_ascii else "│"
        new_prefix = prefix + ("   " if is_last else f"{branch_pipe}  ")
        max_size = node.children[0].size if node.children else 0

        if is_root:
            new_bar_info = None
        else:
            if parent_bar_info:
                new_bar_info = (32 - num_blocks, num_blocks, parent_bar_info[2] + 1)
            else:
                new_bar_info = (32 - num_blocks, num_blocks, 1)

        for i, child in enumerate(node.children):
            print_tree(child, total_root_size, colors, use_color, use_bytes, use_ascii, new_prefix, i == len(node.children) - 1, False, max_size, new_bar_info)

def parse_aggr(aggr_str):
    if not aggr_str: return 1024*1024
    if aggr_str.isdigit(): return int(aggr_str)
    units = {'K': 1024, 'M': 1024*1024, 'G': 1024*1024*1024}
    try:
        if aggr_str[-1].upper() in units:
            return int(aggr_str[:-1]) * units[aggr_str[-1].upper()]
    except:
        pass
    return 1024*1024

def main():
    parser = argparse.ArgumentParser(add_help=False)
    parser.add_argument("-d", "--depth", type=int, default=1)
    parser.add_argument("-a", "--aggr", type=str, default="1M")
    parser.add_argument("-s", "--summary", action="store_true")
    parser.add_argument("-u", "--usage", action="store_true")
    parser.add_argument("-b", "--bytes", action="store_true")
    parser.add_argument("-f", "--files-only", action="store_true")
    parser.add_argument("-x", "--exclude", action="append", default=[])
    parser.add_argument("-H", "--no-hidden", action="store_true")
    parser.add_argument("-A", "--ascii", action="store_true")
    parser.add_argument("-h", "--help", action="store_true")
    parser.add_argument("-v", "--version", action="store_true")
    parser.add_argument("paths", nargs="*")

    args, unknown = parser.parse_known_args()
    # Argparse is a bit tricky with [DEPTH]. Let's just handle it manually if needed.

    if args.help:
        print("Usage: ./executable [options] <path> [<path>..]")
        print("")
        print("Options:")
        print("    -d, --depth [DEPTH] show directories up to depth N (def 1)")
        print("    -a, --aggr [N[KMG]] aggregate smaller than N B/KiB/MiB/GiB (def 1M)")
        print("    -s, --summary       equivalent to -da, or -d1 -a1M")
        print("    -u, --usage         report real disk usage instead of file size")
        print("    -b, --bytes         print sizes in bytes")
        print("    -f, --files-only    skip directories for a fast local overview")
        print("    -x, --exclude NAME  exclude matching files or directories")
        print("    -H, --no-hidden     exclude hidden files")
        print("    -A, --ascii         ASCII characters only, no colors")
        print("    -h, --help          show help")
        print("    -v, --version       print version number")
        return

    if args.version:
        print("dutree version 0.2.18")
        return

    paths = args.paths + unknown
    if not paths:
        paths = ["."]

    depth = args.depth
    aggr_threshold = parse_aggr(args.aggr)
    if args.summary:
        depth = 1
        aggr_threshold = 1024*1024

    use_color = not args.ascii and sys.stdout.isatty()
    colors = parse_ls_colors()

    nodes = []
    for path in paths:
        name = os.path.basename(os.path.abspath(path))
        if path == ".":
            name = os.path.basename(os.getcwd())
        nodes.append(build_tree_full(path, name, args.exclude, args.no_hidden, args.usage, args.files_only))

    if len(nodes) > 1:
        root = Node("", "<collection>", True)
        root.children = nodes
        root.size = sum(n.size for n in nodes)
    else:
        root = nodes[0]

    apply_depth_and_aggregation(root, depth, aggr_threshold)

    global total_root_size
    total_root_size = root.size

