            # Rounding: it seems it rounds to 2 decimal places
            return f"{val:.2f} {unit}"
        val /= 1024
    return f"{val:.2f} PiB"

def get_size(path, use_usage=False):
    try:
        st = os.lstat(path)
        if use_usage:
            # st_blocks is usually in 512-byte blocks
            return st.st_blocks * 512
        else:
            return st.st_size
    except OSError:
        return 0

class Node:
    def __init__(self, path, name, is_dir):
        self.path = path
        self.name = name
        self.is_dir = is_dir
        self.size = 0
        self.children = []

