        elif arg == "-u" or arg == "--usage": args_usage = True
        elif arg == "-b" or arg == "--bytes": args_bytes = True
        elif arg == "-f" or arg == "--files-only": args_files_only = True
        elif arg == "-x" or arg == "--exclude":
