        elif arg == "-H" or arg == "--no-hidden": args_no_hidden = True
        elif arg == "-A" or arg == "--ascii": args_ascii = True
        elif arg == "-h" or arg == "--help": args_help = True
        elif arg == "-v" or arg == "--version": args_version = True
        elif not arg.startswith("-"): args_paths.append(arg)
